local CavalryBannerMaker = {}
local PRODUCTS = {
    pennon = { name = "Kljunasta zastavica", linenCost = 1, paintCost = 1, time = 1, cost = 14, cavalryBoost = 3, prestige = 1, description = "Kljunasta zastavica za viteze." },
    guidon = { name = "Vodilna zastava", linenCost = 2, paintCost = 1, time = 3, cost = 50, cavalryBoost = 6, prestige = 2, description = "Vodilna zastava za eskadrone." },
    standard = { name = "Standard", silkCost = 2, paintCost = 1, threadCost = 1, time = 5, cost = 140, cavalryBoost = 10, prestige = 5, happiness = 1, description = "Standard z družinskim grbom." },
    silk_cavalry_banner = { name = "Svila konjeniška zastava", silkCost = 3, silverCost = 1, threadCost = 1, paintCost = 1, time = 7, cost = 340, cavalryBoost = 14, prestige = 10, happiness = 2, description = "Svilena zastava s srebrnimi nitmi." },
    gold_thread_banner = { name = "Zlatorobna zastava", silkCost = 3, goldCost = 1, threadCost = 1, paintCost = 1, time = 10, cost = 800, cavalryBoost = 20, prestige = 18, happiness = 4, description = "Zlatorobna zastava za plemiške konjeniške čete." },
    royal_cavalry_standard = { name = "Kraljevski konjeniški standard", silkCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, threadCost = 2, paintCost = 2, time = 15, cost = 2200, cavalryBoost = 35, prestige = 55, happiness = 11, description = "Veliki kraljevski konjeniški standard z dragulji in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Konjeniškopraporska delavnica", cost = { gold = 260, wood = 120 }, upkeep = 6, qualityBonus = 5 },
    heraldry_room = { name = "Heraldična soba", cost = { gold = 850, wood = 220, stone = 200, paint = 6 }, upkeep = 20, qualityBonus = 18 },
    gilding_room = { name = "Pozlatnica", cost = { gold = 1900, wood = 300, stone = 400, silver = 25, gold = 6 }, upkeep = 45, qualityBonus = 30 },
    royal_cavalry_atelier = { name = "Kraljevski atelje konjeniških praporov", cost = { gold = 7500, wood = 500, stone = 700, gold = 50, silk = 20 }, upkeep = 140, qualityBonus = 55, prestigeBonus = 33 },
}
CavalryBannerMaker.linenStock = 14; CavalryBannerMaker.silkStock = 12; CavalryBannerMaker.paintStock = 12; CavalryBannerMaker.threadStock = 10; CavalryBannerMaker.silverStock = 6; CavalryBannerMaker.goldStock = 6; CavalryBannerMaker.jewelStock = 6; CavalryBannerMaker.pearlStock = 4
CavalryBannerMaker.productStock = {}; CavalryBannerMaker.buildings = {}; CavalryBannerMaker.maker = nil; CavalryBannerMaker.activeMaking = {}; CavalryBannerMaker.totalProducts = 0; CavalryBannerMaker.dayTimer = 0
function CavalryBannerMaker.init() CavalryBannerMaker.linenStock=14; CavalryBannerMaker.silkStock=12; CavalryBannerMaker.paintStock=12; CavalryBannerMaker.threadStock=10; CavalryBannerMaker.silverStock=6; CavalryBannerMaker.goldStock=6; CavalryBannerMaker.jewelStock=6; CavalryBannerMaker.pearlStock=4; CavalryBannerMaker.productStock={}; CavalryBannerMaker.buildings={}; CavalryBannerMaker.maker=nil; CavalryBannerMaker.activeMaking={}; CavalryBannerMaker.totalProducts=0; CavalryBannerMaker.dayTimer=0; print("[CavalryBannerMaker] Royal Cavalry Banner Maker System initialized (6 products, 4 buildings)") end
function CavalryBannerMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CavalryBannerMaker.maker={name=n or ("Konjeniški praporščak "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Konjeniški praporščak najet: %s (spretnost: %d)",CavalryBannerMaker.maker.name,s),"success") end; return true end
function CavalryBannerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CavalryBannerMaker.build(id) local ok,e=CavalryBannerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CavalryBannerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CavalryBannerMaker.getQualityBonus() local b=0; for _,bd in ipairs(CavalryBannerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CavalryBannerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.linenCost and CavalryBannerMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.silkCost and CavalryBannerMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.paintCost and CavalryBannerMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.threadCost and CavalryBannerMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silverCost and CavalryBannerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CavalryBannerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CavalryBannerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CavalryBannerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CavalryBannerMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CavalryBannerMaker.maker then return false,"Potreben praporščak" end; return true end
function CavalryBannerMaker.make(pt,qty) qty=qty or 1; local ok,e=CavalryBannerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.linenCost then CavalryBannerMaker.linenStock=CavalryBannerMaker.linenStock-d.linenCost*qty end; if d.silkCost then CavalryBannerMaker.silkStock=CavalryBannerMaker.silkStock-d.silkCost*qty end; if d.paintCost then CavalryBannerMaker.paintStock=CavalryBannerMaker.paintStock-d.paintCost*qty end; if d.threadCost then CavalryBannerMaker.threadStock=CavalryBannerMaker.threadStock-d.threadCost*qty end; if d.silverCost then CavalryBannerMaker.silverStock=CavalryBannerMaker.silverStock-d.silverCost*qty end; if d.goldCost then CavalryBannerMaker.goldStock=CavalryBannerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CavalryBannerMaker.jewelStock=CavalryBannerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CavalryBannerMaker.pearlStock=CavalryBannerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CavalryBannerMaker.maker then t=math.max(1,t-math.floor(CavalryBannerMaker.maker.skill/12)) end; table.insert(CavalryBannerMaker.activeMaking,{id="cavbanner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,cavalryBoost=d.cavalryBoost or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CavalryBannerMaker.completeMaking(m) local q=1.0+(CavalryBannerMaker.getQualityBonus()/100); if CavalryBannerMaker.maker then q=q+(CavalryBannerMaker.maker.skill/180) end; q=math.min(2.0,q); CavalryBannerMaker.productStock[m.productType]=(CavalryBannerMaker.productStock[m.productType] or 0)+m.quantity; CavalryBannerMaker.totalProducts=CavalryBannerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CavalryBannerMaker.maker then CavalryBannerMaker.maker.itemsMade=CavalryBannerMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CavalryBannerMaker.maker.skill=math.min(100,CavalryBannerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prapor izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cavalrybanner.completed",{productName=m.productName,cavalryBoost=m.cavalryBoost,prestige=m.prestige}) end end
function CavalryBannerMaker.update(dt) if not _G.state then return end; CavalryBannerMaker.dayTimer=CavalryBannerMaker.dayTimer+dt; if CavalryBannerMaker.dayTimer>=30 then CavalryBannerMaker.dayTimer=0; for i=#CavalryBannerMaker.activeMaking,1,-1 do local m=CavalryBannerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CavalryBannerMaker.completeMaking(m); table.remove(CavalryBannerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CavalryBannerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CavalryBannerMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CavalryBannerMaker.getStats() return {linenStock=CavalryBannerMaker.linenStock,silkStock=CavalryBannerMaker.silkStock,paintStock=CavalryBannerMaker.paintStock,threadStock=CavalryBannerMaker.threadStock,silverStock=CavalryBannerMaker.silverStock,goldStock=CavalryBannerMaker.goldStock,jewelStock=CavalryBannerMaker.jewelStock,pearlStock=CavalryBannerMaker.pearlStock,productStock=CavalryBannerMaker.productStock,numBuildings=#CavalryBannerMaker.buildings,hasMaker=CavalryBannerMaker.maker~=nil,makerName=CavalryBannerMaker.maker and CavalryBannerMaker.maker.name or "—",makerSkill=CavalryBannerMaker.maker and CavalryBannerMaker.maker.skill or 0,activeMaking=#CavalryBannerMaker.activeMaking,totalProducts=CavalryBannerMaker.totalProducts} end
return CavalryBannerMaker
